from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            key = ('id', event['id'])
        else:
            key = ('anonymous', position)

        revision = event.get('revision', 0)
        current = winners.get(key)
        if current is None or (revision, position) > (current[0], current[1]):
            winners[key] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in sorted(winners.values(), key=lambda winner: winner[1]):
        if event.get('void', False):
            continue

        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances.setdefault(key, 0)
        balances[key] += amount(event, data.get('rounding'))

    return {'balances': balances}

def _round_bp(numerator, mode):
    if mode == 'floor':
        return numerator // 10000
    return (numerator + 5000) // 10000


def amount(event, mode):
    value = event['price'] * event.get('quantity', 1)
    discount_bp = min(10000, max(0, event.get('discount_bp', 0)))
    net = _round_bp(value * (10000 - discount_bp), mode)

    tax_bp = event.get('tax_bp', 0)
    total = net + _round_bp(net * tax_bp, mode)

    if event.get('kind') == 'refund':
        return -total
    return total
